#!/usr/bin/env node
/**
 * diligent: CLI entry point. A thin dispatcher; the logic lives in scripts/.
 * Zero dependencies, Node >= 20, no network access.
 */
import { spawn } from 'node:child_process';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describeEngine, nativeDelegates } from '../scripts/lib/engine.mjs';
import { probeBinary } from '../scripts/lib/orchestrate/engine.mjs';
import { DILIGENT_VERSION } from '../scripts/lib/cli.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const UTILITIES = {
  init: 'init.mjs',
  status: 'status.mjs',
  gate: 'gate.mjs',
  report: 'report.mjs',
  audit: 'audit.mjs',
  sarif: 'sarif.mjs',
  baseline: 'baseline.mjs',
  diff: 'diff.mjs',
  'validate-skill': 'validate-skill.mjs',
  install: 'install.mjs',
  check: 'check.mjs',
  test: 'test.mjs'
};
const AGENT_PHASES = ['discover', 'scope', 'inventory', 'plan', 'collect', 'assess', 'propose', 'verify', 'resume'];

function usage() {
  return `diligent: audit a U.S. government website for accessibility and federal web obligations

Version ${DILIGENT_VERSION} is a contracts-and-gate release. It ships zero automated website checks.

Usage:
  diligent [--json] <command> [arguments]
  diligent --help | --version

CLI commands (implemented):
  init <audit-id>            create .diligent/<audit-id>/ with frozen authority and rule locks
  status <audit-id>          pipeline state and artifact validity
  gate <audit-id>            recompute the assessment deterministically (exit 0/1/2/3)
  report <audit-id>          render REPORT.md from ASSESSMENT.json
  audit --url <https://host/>  run the whole chain with the diligent-rs companion binary (see docs/audit-command.md)
  rules validate             validate authorities, rule packs and profiles
  validate-skill             check skill frontmatter, paths and versions
  install                    copy the skill to ~/.agents/skills/diligent
  check                      run all checks
  test                       run the unit and fixture tests

Agent-performed phases (guided by skills/<phase>/SKILL.md, no CLI implementation in ${DILIGENT_VERSION}):
  ${AGENT_PHASES.join(', ')}

Global options:
  --json        machine-readable output where supported
  DILIGENT_ENGINE=node  environment: never delegate gate or rules validate to diligent-rs
  -h, --help    show help (also: diligent <command> --help)
  -v, --version print the version

Gate exit codes: 0 pass for declared scope, 1 mandatory failure, 2 incomplete, 3 invalid input.
Diligent is not a government service and does not certify anything.
`;
}

async function readVersion() {
  return JSON.parse(await readFile(join(ROOT, 'package.json'), 'utf8')).version;
}

function runScript(script, args) {
  return new Promise(resolvePromise => {
    const child = spawn(process.execPath, [join(ROOT, 'scripts', script), ...args], { stdio: 'inherit' });
    child.on('error', error => { console.error(`diligent: failed to start ${script}: ${error.message}`); resolvePromise(3); });
    child.on('close', (code, signal) => resolvePromise(signal ? 1 : code ?? 1));
  });
}

/**
 * `gate` and `rules validate` run the diligent-rs binary when one reporting protocol 1 is present
 * (and DILIGENT_ENGINE is not "node"). Returns the exit code, or null when Node should run the script.
 */
function runNative(args, label) {
  if (!nativeDelegates()) return null;
  const probe = probeBinary();
  if (!probe.ok) return null;
  return new Promise(resolvePromise => {
    const child = spawn(probe.binary, args, { stdio: 'inherit' });
    child.on('error', error => { console.error(`diligent: failed to start ${label}: ${error.message}`); resolvePromise(3); });
    child.on('close', (code, signal) => resolvePromise(signal ? 1 : code ?? 1));
  });
}

async function main(argv) {
  const json = argv.includes('--json');
  const args = argv.filter(arg => arg !== '--json');
  const [command, ...rest] = args;

  if (!command || command === '--help' || command === '-h' || command === 'help') {
    process.stdout.write(usage());
    return 0;
  }
  if (command === '--version' || command === '-v') {
    const version = await readVersion();
    if (json) console.log(JSON.stringify({ name: 'diligent', version, engine: describeEngine() }, null, 2));
    else console.log(version);
    return 0;
  }
  if (command === 'rules') {
    if (rest[0] === 'validate') {
      const tail = [...rest.slice(1), ...(json ? ['--json'] : [])];
      const hasRoot = tail.some(arg => arg === '--data-root' || arg.startsWith('--data-root='));
      const native = runNative(['rules', 'validate', ...(hasRoot ? [] : ['--data-root', ROOT]), ...tail], 'diligent-rs rules validate');
      return native ?? runScript('validate-rules.mjs', tail);
    }
    if (!rest[0] || rest[0] === '--help' || rest[0] === '-h') { console.log('Usage: diligent rules validate [--data-root <dir>] [--json]'); return rest[0] ? 0 : 2; }
    console.error(`diligent: unknown rules command "${rest[0]}". Use "diligent rules validate".`);
    return 2;
  }
  if (command === 'gate') {
    const gateArgs = [...rest, ...(json ? ['--json'] : [])];
    const native = runNative(['gate', ...gateArgs], 'diligent-rs gate');
    return native ?? runScript(UTILITIES.gate, gateArgs);
  }
  if (command in UTILITIES) return runScript(UTILITIES[command], [...rest, ...(json ? ['--json'] : [])]);
  if (AGENT_PHASES.includes(command)) {
    const message = `${command} is an agent-performed phase in ${DILIGENT_VERSION} and has no executable implementation. Read ${command === 'resume' ? 'references/workflow.md' : `skills/${command}/SKILL.md`}.`;
    if (json) console.log(JSON.stringify({ command, status: 'not_implemented', exit_code: 3, message, engine: describeEngine() }, null, 2));
    else console.error(message);
    return 3;
  }
  console.error(`diligent: unknown command "${command}". Run "diligent --help".`);
  return 2;
}

main(process.argv.slice(2)).then(code => { process.exitCode = code; }, error => {
  console.error(`diligent: ${error.stack || error.message}`);
  process.exitCode = 3;
});

/**
 * Vite plugin that stamps native elements with the place they were written:
 * data-diligent-src="<path relative to root>:<line>".
 *
 * Works on JSX/TSX, Vue (outside script and style blocks), Svelte and Astro
 * sources. It lexes tags tolerantly, with no dependencies and no parser, the
 * same way the Rust source pass reads template files. Components (uppercase or
 * dotted names), fragments, built-in framework elements and tags that already
 * carry the attribute are left alone. It produces no source map: the attribute
 * goes right after the tag name, so only that line shifts, to the right.
 *
 * Private to this repository; not published, not in the npm package.
 */
import { relative, sep } from 'node:path';

export const ATTRIBUTE = 'data-diligent-src';

const EXTENSIONS = new Map([
  ['.jsx', 'jsx'],
  ['.tsx', 'jsx'],
  ['.vue', 'vue'],
  ['.svelte', 'svelte'],
  ['.astro', 'astro']
]);

const VOID = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source',
  'track', 'wbr'
]);

// Never stamped: raw text, and elements the frameworks treat specially.
const SKIP_TAGS = new Set([
  'script', 'style', 'template', 'slot', 'component', 'transition', 'transition-group',
  'keep-alive', 'teleport', 'suspense'
]);

const MAX_DEPTH = 64;

function isWs(c) {
  return c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === '\f';
}

function isAlpha(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

function isWordChar(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c === '_' || c === '$';
}

/** Start offset of each line. A line ends at \n, \r\n or a lone \r. */
function lineStarts(code) {
  const starts = [0];
  for (let i = 0; i < code.length; i++) {
    const c = code[i];
    if (c === '\n') starts.push(i + 1);
    else if (c === '\r' && code[i + 1] !== '\n') starts.push(i + 1);
  }
  return starts;
}

function lineOf(starts, offset) {
  let lo = 0;
  let hi = starts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (starts[mid] <= offset) lo = mid;
    else hi = mid - 1;
  }
  return lo + 1;
}

/** Index just past the JS string or template literal starting at i. */
function stringEnd(code, i, depth = 0) {
  const q = code[i];
  let j = i + 1;
  while (j < code.length) {
    const c = code[j];
    if (c === '\\') j += 2;
    else if (c === q) return j + 1;
    else if (c === '\n' && q !== '`') return j;
    else if (q === '`' && c === '$' && code[j + 1] === '{') j = braceEnd(code, j + 1, depth + 1) + 1;
    else j++;
  }
  return code.length;
}

/** Index of the } that closes the { at i, or the text length. */
function braceEnd(code, i, depth = 0) {
  if (depth > MAX_DEPTH) return code.length;
  let level = 0;
  let j = i;
  while (j < code.length) {
    const c = code[j];
    if (c === '{') level++;
    else if (c === '}') {
      level--;
      if (level <= 0) return j;
    } else if (c === '"' || c === "'" || c === '`') {
      j = stringEnd(code, j, depth);
      continue;
    }
    j++;
  }
  return code.length;
}

const KEYWORDS_BEFORE_JSX = new Set([
  'return', 'default', 'case', 'yield', 'await', 'in', 'of', 'else', 'do', 'typeof', 'void', 'throw'
]);

/** True when the text before i lets a JSX element start at i. */
function jsxAllowedBefore(code, i) {
  let j = i;
  while (j > 0 && isWs(code[j - 1])) j--;
  if (j === 0) return true;
  const p = code[j - 1];
  if (isWordChar(p)) {
    let k = j;
    while (k > 0 && isWordChar(code[k - 1])) k--;
    return KEYWORDS_BEFORE_JSX.has(code.slice(k, j));
  }
  return p !== ')' && p !== ']' && p !== '.';
}

function indexOfCI(code, needle, from) {
  const lower = code.toLowerCase();
  return lower.indexOf(needle, from);
}

/**
 * Reads a start tag at i (code[i] === '<', next is a letter). Returns
 * { name, nameEnd, end, selfClosing } where end is just past the '>'.
 */
function readTag(code, i, flavor) {
  let nameEnd = i + 1;
  while (nameEnd < code.length && !isWs(code[nameEnd]) && code[nameEnd] !== '/' && code[nameEnd] !== '>') nameEnd++;
  const name = code.slice(i + 1, nameEnd);
  let j = nameEnd;
  let selfClosing = false;
  while (j < code.length) {
    const c = code[j];
    if (c === '>') {
      j++;
      return { name, nameEnd, end: j, selfClosing };
    }
    if (c === '/' && code[j + 1] === '>') {
      return { name, nameEnd, end: j + 2, selfClosing: true };
    }
    if (c === '"' || c === "'") {
      const close = code.indexOf(c, j + 1);
      j = close === -1 ? code.length : close + 1;
    } else if (c === '{' && flavor !== 'vue') {
      j = Math.min(braceEnd(code, j) + 1, code.length);
    } else {
      j++;
    }
  }
  return { name, nameEnd, end: code.length, selfClosing, unterminated: true };
}

function hasAttribute(tagText) {
  return new RegExp(`[\\s"'}]${ATTRIBUTE}(?=[\\s=/>]|$)`).test(tagText);
}

function isNative(name) {
  return /^[a-z][a-z0-9-]*$/.test(name) && !SKIP_TAGS.has(name);
}

/** End of the leading --- frontmatter block in an Astro file, or 0. */
function astroFrontmatterEnd(code) {
  const m = /^(﻿?\s*)---[ \t]*\r?\n/.exec(code);
  if (!m) return 0;
  const close = /\r?\n---[ \t]*(\r?\n|$)/.exec(code.slice(m[0].length - 1));
  if (!close) return 0;
  return m[0].length - 1 + close.index + close[0].length;
}

/**
 * Finds the offset where each stampable tag's name ends.
 * Returns [{ offset: nameEnd, tagStart }].
 */
export function findStampPoints(code, flavor) {
  const points = [];
  const stack = [{ kind: flavor === 'jsx' ? 'js' : 'root', depth: 0, braces: 0 }];
  let i = flavor === 'astro' ? astroFrontmatterEnd(code) : 0;
  const top = () => stack[stack.length - 1];

  const handleTag = (at) => {
    const next = code[at + 1];
    if (next === '>') {
      // Fragment: opens an element, never stamped.
      if (top().kind === 'js') stack.push({ kind: 'markup', depth: 1, braces: 0 });
      else top().depth++;
      return at + 2;
    }
    const tag = readTag(code, at, flavor);
    const lower = tag.name.toLowerCase();
    const rawText = (flavor !== 'jsx') && (lower === 'script' || lower === 'style');
    if (rawText) {
      const close = indexOfCI(code, `</${lower}`, tag.end);
      if (close === -1) return code.length;
      const gt = code.indexOf('>', close);
      return gt === -1 ? code.length : gt + 1;
    }
    const tagText = code.slice(at, tag.end);
    if (isNative(tag.name) && !tag.unterminated && !hasAttribute(tagText)) {
      points.push({ offset: tag.nameEnd, tagStart: at });
    }
    const opens = !tag.selfClosing && !(flavor !== 'jsx' && VOID.has(lower));
    if (opens) {
      if (top().kind === 'js') stack.push({ kind: 'markup', depth: 1, braces: 0 });
      else top().depth++;
    } else if (top().kind === 'js') {
      // A lone self-closing element inside an expression: nothing to track.
    }
    return tag.end;
  };

  const handleEndTag = (at) => {
    const gt = code.indexOf('>', at);
    const t = top();
    if (t.kind === 'markup') {
      t.depth--;
      if (t.depth <= 0) stack.pop();
    } else if (t.kind === 'root') {
      t.depth = Math.max(0, t.depth - 1);
    }
    return gt === -1 ? code.length : gt + 1;
  };

  while (i < code.length) {
    const t = top();
    const c = code[i];
    const inMarkup = t.kind !== 'js';
    if (inMarkup) {
      if (c === '<') {
        if (code.startsWith('<!--', i)) {
          const end = code.indexOf('-->', i + 4);
          i = end === -1 ? code.length : end + 3;
        } else if (code[i + 1] === '/') {
          i = handleEndTag(i);
        } else if (isAlpha(code[i + 1] ?? '') || code[i + 1] === '>') {
          i = handleTag(i);
        } else {
          i++;
        }
      } else if (c === '{' && flavor === 'vue' && code[i + 1] === '{') {
        const end = code.indexOf('}}', i + 2);
        i = end === -1 ? code.length : end + 2;
      } else if (c === '{' && flavor !== 'vue') {
        const n = code[i + 1];
        if (flavor === 'svelte' && (n === '#' || n === ':' || n === '/' || n === '@')) {
          i = Math.min(braceEnd(code, i) + 1, code.length);
        } else if (stack.length < MAX_DEPTH) {
          stack.push({ kind: 'js', depth: 0, braces: 0 });
          i++;
        } else {
          i++;
        }
      } else {
        i++;
      }
      continue;
    }
    // JavaScript context: top level of a JSX file, or inside { }.
    if (c === '"' || c === "'" || c === '`') {
      i = stringEnd(code, i);
    } else if (c === '/' && code[i + 1] === '/') {
      const nl = code.indexOf('\n', i);
      i = nl === -1 ? code.length : nl;
    } else if (c === '/' && code[i + 1] === '*') {
      const end = code.indexOf('*/', i + 2);
      i = end === -1 ? code.length : end + 2;
    } else if (c === '{') {
      t.braces++;
      i++;
    } else if (c === '}') {
      if (t.braces === 0 && stack.length > 1) stack.pop();
      else t.braces = Math.max(0, t.braces - 1);
      i++;
    } else if (c === '<' && (isAlpha(code[i + 1] ?? '') || code[i + 1] === '>') && jsxAllowedBefore(code, i)) {
      i = handleTag(i);
    } else {
      i++;
    }
  }
  return points;
}

/**
 * Adds data-diligent-src to every native element in code. `file` is the path
 * written into the attribute. Returns the new code, or null when nothing changed.
 */
export function stampSource(code, flavor, file) {
  const points = findStampPoints(code, flavor);
  if (points.length === 0) return null;
  const starts = lineStarts(code);
  const safe = file.split(sep).join('/').replace(/"/g, '&quot;');
  let out = '';
  let last = 0;
  for (const { offset, tagStart } of points) {
    out += code.slice(last, offset);
    out += ` ${ATTRIBUTE}="${safe}:${lineOf(starts, tagStart)}"`;
    last = offset;
  }
  out += code.slice(last);
  return out;
}

/**
 * @param {{ enabled?: boolean, root?: string }} [options]
 *   enabled: stamp files. Default: true when Vite's mode is "development".
 *   root: paths in the attribute are relative to this. Default: Vite's root.
 */
export function diligentSrc(options = {}) {
  let enabled = options.enabled;
  let root = options.root;
  return {
    name: 'diligent-src',
    enforce: 'pre',
    configResolved(config) {
      if (enabled === undefined) enabled = config.mode === 'development';
      if (root === undefined) root = config.root;
    },
    transform(code, id) {
      if (enabled !== true) return null;
      const queryAt = id.indexOf('?');
      const file = queryAt === -1 ? id : id.slice(0, queryAt);
      const query = queryAt === -1 ? '' : id.slice(queryAt + 1);
      // Compiled sub-requests of a single-file component are not source.
      if (query.split('&').some(part => part === 'vue' || part === 'raw' || part === 'url' || part.startsWith('type='))) return null;
      const dot = file.lastIndexOf('.');
      const flavor = dot === -1 ? undefined : EXTENSIONS.get(file.slice(dot).toLowerCase());
      if (!flavor || file.includes('node_modules')) return null;
      const shown = root ? relative(root, file) : file;
      const out = stampSource(code, flavor, shown);
      return out === null ? null : { code: out, map: null };
    }
  };
}

export default diligentSrc;

/** Tiny argument parser shared by the scripts. No dependencies. */
import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { UsageError } from './artifacts.mjs';

/** The package version, read once at load from package.json. Every user-visible version string uses this. */
export const DILIGENT_VERSION = JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8')).version;

/** True when the module at `metaUrl` is the process entry point (works across symlinks and platforms). */
export function isMain(metaUrl) {
  if (!process.argv[1]) return false;
  try { return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(metaUrl)); } catch { return false; }
}

/**
 * parseArgs(argv, { flags: { name: 'boolean' | 'string' }, aliases })
 * Returns { positional, options }. Unknown --options are an error.
 */
export function parseArgs(argv, spec = {}) {
  const flags = { help: 'boolean', ...spec };
  const options = {};
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h') { options.help = true; continue; }
    if (token === '--') { positional.push(...argv.slice(i + 1)); break; }
    if (!token.startsWith('--')) { positional.push(token); continue; }
    const [rawName, inline] = token.slice(2).split(/=(.*)/s, 2);
    const kind = flags[rawName];
    if (!kind) throw new UsageError(`unknown option --${rawName}. Run with --help.`);
    if (kind === 'boolean') {
      if (inline !== undefined) throw new UsageError(`option --${rawName} does not take a value.`);
      options[rawName] = true;
    } else {
      const value = inline !== undefined ? inline : argv[++i];
      if (value === undefined || (inline === undefined && value.startsWith('--'))) throw new UsageError(`option --${rawName} requires a value.`);
      options[rawName] = value;
    }
  }
  return { positional, options };
}

/** Run a script main function with uniform error and exit-code handling. */
export async function runMain(main) {
  try {
    const code = await main();
    process.exitCode = typeof code === 'number' ? code : 0;
  } catch (error) {
    if (error instanceof UsageError) {
      console.error(`diligent: ${error.message}`);
      process.exitCode = 2;
    } else {
      console.error(`diligent: ${error.stack || error.message}`);
      process.exitCode = 3;
    }
  }
}
